function fitWindows(){
 const W=innerWidth,H=innerHeight;
 const side=Math.max(360,Math.min(440,Math.round(W*.28)));
 const top=64,bottom=80,gap=20,left=W>1150?112:92;
 const available=Math.max(480,H-top-bottom);
 const main=Math.max(440,Math.min(1280,W-side-left-48));
 const chatHeight=Math.max(260,Math.min(340,Math.round(available*.35)));
 for(const id of ['files','reader','browser','space'])Object.assign(wins[id],{x:left,y:top,w:main,h:available});
 Object.assign(wins.chat,{x:W-side-24,y:top,w:side,h:chatHeight});
 Object.assign(wins.notes,{x:W-side-24,y:top+chatHeight+gap,w:side,h:Math.max(260,available-chatHeight-gap)});
}
fitWindows();
const paths={folder:'M3 6h6l2 2h10v12H3z',file:'M6 3h8l4 4v14H6z M14 3v5h5 M9 12h6 M9 16h6',chat:'M3 4h18v13H8l-5 4z M7 9h10 M7 13h7',browser:'M3 4h18v16H3z M3 8h18 M6 6h.1 M9 6h.1 M12 11a3 3 0 1 0 0 6 3 3 0 0 0 0-6z',notes:'M5 3h14v18H5z M9 7h6 M9 11h6 M9 15h4',space:'M12 3l9 5v9l-9 5-9-5V8z M3 8l9 5 9-5 M12 13v9 M8 5l9 5',photo:'M3 4h18v16H3z M4 17l5-5 4 3 3-4 5 6 M16 8h.1',video:'M3 5h14v14H3z M17 9l4-3v12l-4-3 M9 9l4 3-4 3z',close:'M5 5l14 14 M19 5L5 19',min:'M5 15h14',max:'M5 5h14v14H5z',sound:'M4 10h4l5-5v14l-5-5H4z M17 8q5 4 0 8',search:'M10 4a6 6 0 1 0 0 12 6 6 0 0 0 0-12 M15 15l6 6',back:'M14 5l-7 7 7 7',pin:'M8 3h8l-1 7 4 4H5l4-4z M12 14v7',check:'M5 12l4 4L19 6',home:'M3 10l9-7 9 7 M6 9v12h12V9',drive:'M4 5h16v14H4z M4 14h16 M16 17h.1',power:'M12 2v9 M6 5a9 9 0 1 0 12 0',phone:'M6 3h4l2 5-3 2a12 12 0 0 0 5 5l2-3 5 2v4a2 2 0 0 1-2 2A17 17 0 0 1 4 5a2 2 0 0 1 2-2z',more:'M5 12h.1 M12 12h.1 M19 12h.1',emoji:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18z M9 10h.1 M15 10h.1 M8.5 14a4.5 4.5 0 0 0 7 0',zoomin:'M10 4a6 6 0 1 0 0 12 6 6 0 0 0 0-12z M15 15l6 6 M10 7v6 M7 10h6',zoomout:'M10 4a6 6 0 1 0 0 12 6 6 0 0 0 0-12z M15 15l6 6 M7 10h6',refresh:'M20 12a8 8 0 1 1-2.3-5.7 M18 3v4h-4',lock:'M6 11h12v9H6z M9 11V8a3 3 0 0 1 6 0v3',contact:'M12 10.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7z M4.5 20a7.5 7.5 0 0 1 15 0',cube:'M12 3l8 4.6v8.8L12 21l-8-4.6V7.6L12 3z M12 12.2l8-4.6 M12 12.2l-8-4.6 M12 12.2V21',circleF:'M12 4a8 8 0 1 0 .01 0z M12 9.2a2.8 2.8 0 1 1 0 5.6 2.8 2.8 0 0 1 0-5.6z',scissors:'M7 4l8.5 8.5 M17 4L9.5 11.5 M7.5 18.5a2.5 2.5 0 1 1 0-5 2.5 2.5 0 0 1 0 5z M7.5 18.5L15 11 M16.5 18.5a2.5 2.5 0 1 1 0-5 2.5 2.5 0 0 1 0 5z',mic:'M12 3.5a2.8 2.8 0 0 1 2.8 2.8v4.7a2.8 2.8 0 0 1-5.6 0V6.3A2.8 2.8 0 0 1 12 3.5z M6.5 10.8a5.5 5.5 0 0 0 11 0 M12 16.5V20 M9 20h6',menu3:'M4 7h16 M4 12h16 M4 17h16',plusC:'M12 3.5a8.5 8.5 0 1 0 0 17 8.5 8.5 0 0 0 0-17z M12 8.2v7.6 M8.2 12h7.6',caret:'M7 10l5 5 5-5'};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));saveFailed=false}catch{saveFailed=true}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300)}
function tone(kind='message'){if(!state.audio)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.connect(gain);gain.connect(audioCtx.destination);osc.type='sine';osc.frequency.setValueAtTime(kind==='message'?520:260,audioCtx.currentTime);gain.gain.setValueAtTime(.012,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.22);osc.start();osc.stop(audioCtx.currentTime+.23)}catch{}}
function addMessage(text,who='lu',attachment){state.messages.push({text,who,attachment,time:storyTime()});if(who==='lu'){ui.unread++;tone()}save()}
function storyTime(){const mins=12+state.stage*4;return `${14+Math.floor(mins/60)}:${String(mins%60).padStart(2,'0')}`}
const TYPE_KEY='no-outside.typing.v1';let pending=[],typeTimer=0;
function queueLu(text,attachment,delay){pending.push({text,attachment,delay});if(!typeTimer)deliverNext()}
function deliverNext(){const item=pending[0];const chatHere=typeof pane==='undefined'||pane==='chat';if(!item){ui.typing=false;typeTimer=0;try{localStorage.removeItem(TYPE_KEY)}catch{}if(chatHere)render();return}ui.typing=true;try{localStorage.setItem(TYPE_KEY,JSON.stringify(Date.now()))}catch{}if(chatHere)render();typeTimer=setTimeout(()=>{pending.shift();addMessage(item.text,'lu',item.attachment);typeTimer=setTimeout(deliverNext,420)},item.delay??(700+Math.random()*900))}
function flushPending(){clearTimeout(typeTimer);ui.typing=false;try{localStorage.removeItem(TYPE_KEY)}catch{}while(pending.length){const item=pending.shift();addMessage(item.text,'lu',item.attachment)}}
function chatBusy(){return pending.length>0||ui.typing}
function luReply(kind){const pool=(chatReplies[kind]||[])[state.stage]||{s:['……'],v:['……'],f:'……'};const key=kind+':'+state.stage;const n=ui.chatTally[key]||0;ui.chatTally[key]=n+1;return {self:pool.s[Math.min(n,pool.s.length-1)],reply:n<pool.v.length?pool.v[n]:pool.f}}
function wxRow(m,prev){if(m.who==='system')return `<div class="wx-sys">${esc(m.text)}</div>`;const self=m.who==='self';const time=prev&&prev.time===m.time?'':`<div class="wx-time">${esc(m.time)}</div>`;const avatar=`<div class="wx-avatar ${self?'wx-me':'wx-lu'}">${self?'许':'陆'}</div>`;const body=m.attachment?`<button class="wx-file" data-action="doc" data-id="${m.attachment}">${icon('file')}<span class="wx-file-main"><b>${esc(docs.find(d=>d.id===m.attachment)?.title||'附件')}</b><small>HC_ARCHIVE · 收到的文件</small></span></button>`:`<p>${esc(m.text)}</p>`;return `${time}<div class="wx-row ${self?'self':''}">${avatar}<div class="wx-pop">${body}</div></div>`}
function readSection(i){const p=puzzles[i],h=state.history.find(x=>x.stage===i);const names={observe:'观察对窗与重复物件',test:'11月8日做杯子测试',retreat:'搬离客厅，取消视频会议'};return `<p class="on-eyebrow">第 ${i+1} 节 · 已核对</p><h3>${p.q}</h3><div class="on-record">${p.type==='timeline'?[0,1,2].map(x=>`<p><em>${x+1}</em>${h?esc(names[h.answer[x]]):'—'}</p>`).join(''):p.input?`<p class="picked"><em>答</em>${h?esc(h.answer):'—'}${h?'<i>✓</i>':''}</p>`:p.options.map((o,x)=>`<p class="${h&&h.answer===x?'picked':''}"><em>${'ABC'[x]}</em>${esc(o)}${h&&h.answer===x?'<i>✓</i>':''}</p>`).join('')}</div>`}
function start(reset=false){if(reset)state=fresh();if(!state.started){state.started=true;state.messages=introMessages.map(([time,text])=>({time,text,who:'lu'}));}save();render();if(reset||!state.seen.length&&!state.flags.length)openDoc('room')}
function render(){if(state.ending){renderEnding();return}if(!state.started){state.started=true;state.messages=introMessages.map(([time,text])=>({time,text,who:'lu'}));save()}renderDesktop()}
function renderDesktop(){
  const scrolls={};document.querySelectorAll('.window-content').forEach(el=>scrolls[el.dataset.win]=el.scrollTop);
  $('#app').innerHTML=`<main class="desktop"><header class="topbar"><strong>许澄的工作台</strong><div class="right"><span class="mono">HC_ARCHIVE</span><span class="small-dot"></span><span>硬盘已连接</span><button data-action="menu">会话</button></div></header><div class="desktop-icons">${[['files','folder','移动硬盘','folder-icon'],['browser','browser','浏览器','browser-icon'],['chat','chat','陆遥','chat-icon'],['space','space','空间复核',''],['notes','notes','调查便签','notes-icon']].map(([id,i,label,cls])=>`<button class="desktop-icon" data-action="open-window" data-id="${id}">${icon(i,cls)}<span>${label}</span></button>`).join('')}</div><div class="desktop-watermark"><b>没有窗外</b><p>松亭公寓 · 影像复核</p></div>${Object.entries(wins).filter(([id,w])=>w.open).map(([id,w])=>windowHTML(id,w)).join('')}<footer class="taskbar"><button class="start" data-action="menu">${icon('home')}工作台</button>${Object.entries(wins).filter(([,w])=>w.open).map(([id,w])=>`<button class="task ${!w.min&&w.z===highest?'active':''}" data-action="task" data-id="${id}" title="${esc(w.title)}">${icon(({files:'folder',reader:'photo',notes:'notes',chat:'chat',space:'space',browser:'browser'})[id])}<span>${({files:'硬盘',reader:'影像',notes:'便签',chat:'陆遥',space:'复核',browser:'搜索'})[id]}</span>${id==='chat'&&ui.unread?'<i class="unread"></i>':''}</button>`).join('')}<div class="tray"><span class="saving">${saveFailed?'进度未能写入':'已保存'}</span><button data-action="audio" title="切换声音">${icon('sound')}<span>${state.audio?'声音开启':'静音'}</span></button><span class="mono">${storyTime()}</span></div></footer></main>`;
  document.querySelectorAll('.window-content').forEach(el=>{el.scrollTop=scrolls[el.dataset.win]||0});
  const chat=$('.wx-messages');if(chat)chat.scrollTop=chat.scrollHeight;
  bindWindowGestures();
}
function windowHTML(id,w){return `<section class="window ${w.min?'minimized':''} ${w.z===highest?'focused':''}" data-window="${id}" style="left:${w.x}px;top:${w.y}px;width:${w.w}px;height:${w.h}px;z-index:${w.z}"><header class="window-header" data-drag="${id}"><div class="window-title">${icon(({files:'folder',reader:'photo',notes:'notes',chat:'chat',space:'space',browser:'browser'})[id])}<span>${esc(w.title)}</span></div><div class="window-controls"><button data-action="min" data-id="${id}" title="最小化">${icon('min')}</button><button data-action="maximize" data-id="${id}" title="调整窗口">${icon('max')}</button><button class="close" data-action="close" data-id="${id}" title="关闭窗口">${icon('close')}</button></div></header><div class="window-content" data-win="${id}">${({files:filesView,browser:browserView,chat:chatView,notes:notesView,reader:readerView,space:spaceView})[id]()}</div><div class="resize-handle" data-resize="${id}"></div></section>`}
function focus(id){if(!wins[id])return;wins[id].open=true;wins[id].min=false;wins[id].z=++highest;if(id==='chat')ui.unread=0}
function openWindow(id){focus(id);render()}
function availableDocs(){return docs.filter(d=>d.folder!=='现场回传'||state.stage>=6||d.id==='entrance'&&state.stage>=5)}
function filesView(){const folders=['全部文件','原始影像','交付件','青苇工作间','项目文件','现场回传','工作记录'];const q=ui.localSearch.toLowerCase();const items=availableDocs().filter(d=>d.kind!=='web'&&(ui.folder==='全部文件'||d.folder===ui.folder)&&(!q||(d.title+d.tags).toLowerCase().includes(q)));return `<div class="toolbar"><form class="searchbar" data-form="file-search"><input name="query" aria-label="搜索硬盘文件" value="${esc(ui.localSearch)}" placeholder="搜索文件名、人物或内容"><button>搜索</button></form></div><div class="file-layout"><nav class="file-sidebar"><h4>HC_ARCHIVE</h4>${folders.map(f=>`<button class="${f===ui.folder?'active':''}" data-action="folder" data-id="${f}">${icon(f==='全部文件'?'drive':'folder')}${f}</button>`).join('')}</nav><div class="file-main"><div class="file-head">名称<span style="margin-left:auto">单击打开</span></div>${!q&&['全部文件','原始影像'].includes(ui.folder)?`<button class="file-row" data-action="doc" data-id="room">${icon('photo')}<div><b>041-W03_客厅西窗.jpg</b><small>原始影像 · 已恢复</small></div></button>`:''}${items.map(d=>`<button class="file-row" data-action="doc" data-id="${d.id}">${icon(d.kind==='video'?'video':'file')}<div><b>${esc(d.title)}</b><small>${esc(d.folder)}</small></div>${state.seen.includes(d.id)?'<span class="seen">已读</span>':''}</button>`).join('')}${!items.length&&q?'<div class="empty">没有找到对应文件。可以试试人物名或资料里出现的短语。</div>':''}<div class="file-footer">原始记录只读 · ${items.length}项资料</div></div></div>`}
function browserView(){const results=ui.lastSearch?search(ui.lastSearch).filter(d=>d.folder!=='现场回传'||state.stage>=6):[];const url=ui.lastSearch?`luwei.search/s?q=${encodeURIComponent(ui.lastSearch)}`:'luwei.search';return `<div class="edg-root"><div class="edg-tabs"><span class="edg-tab">${icon('search','edg-fav')}<span>芦苇搜索</span><i class="edg-x" title="关闭标签页">×</i></span><button class="edg-newtab" title="新建标签页" disabled>＋</button></div><div class="edg-nav"><button class="edg-navbtn" data-action="search-home" title="主页">${icon('home')}</button><button class="edg-navbtn" data-action="edg-reload" title="刷新">${icon('refresh')}</button><form class="edg-address" data-form="browser-search"><span class="edg-lock">${icon('lock')}</span><input name="query" aria-label="搜索网页与档案" value="${esc(url)}" placeholder="搜索或输入网址" autocomplete="off" spellcheck="false"></form><button class="edg-navbtn" title="收藏此页" disabled>${icon('pin')}</button></div>${!ui.lastSearch?`<div class="edg-page"><div class="browser-home"><h2 class="browser-logo">芦苇搜索</h2><p class="search-tagline">网页、旧帖，以及留下来的东西。</p><p class="muted" style="font-size:15px;line-height:2">输入照片或资料里出现的名字。<br>搜索过的词会保存在下面。</p><div class="search-suggestions">${state.history.filter(x=>x.query).slice(-8).map(x=>`<button data-action="query" data-id="${esc(x.query)}">${esc(x.query)}</button>`).join('')}</div></div></div>`:`<div class="edg-page"><div class="search-results"><p class="search-count">“${esc(ui.lastSearch)}” · ${results.length}条相关存档</p>${results.map(d=>`<article class="search-result"><div class="result-url">${esc(d.url||'本地档案 / '+d.folder)}</div><button data-action="doc" data-id="${d.id}">${esc(d.title)}</button><p>${esc(d.body.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').slice(0,115))}…</p></article>`).join('')}${!results.length?'<div class="empty">没有找到相关记录。<br>可以换成较短的词，或从已读资料复制名字。</div>':''}</div></div>`}</div>`}
