function wxRail(){return `<aside class="wx-rail"><div class="wx-avatar wx-me wx-me-rail">许</div><button class="wx-nav on" title="聊天">${icon('chat')}<i class="wx-red-dot ${ui.unread?'':'none'}"></i></button><span class="wx-nav" title="通讯录">${icon('contact')}</span><span class="wx-nav" title="收藏">${icon('cube')}</span><span class="wx-nav" title="朋友圈">${icon('circleF')}<i class="wx-badge">1</i></span><span class="wx-rail-pad"></span><span class="wx-nav dim" title="手机">${icon('phone')}</span><span class="wx-menu-wrap wx-nav-wrap dim" data-action="wx-menu" data-id="rail" title="设置及其他"><span class="wx-nav">${icon('menu3')}<i class="wx-red-dot"></i></span>${ui.openMenu==='rail'?wxMenu('rail',true):''}</span></aside>`}
function wxList(){const last=[...state.messages].reverse().find(m=>m.who!=='system');const preview=last?`${last.who==='self'?'你：':''}${last.text}`:'……';const status=state.stage>=7?'文字连接 · 语音不稳定':state.stage>=6?'现场连接':'在线';return `<aside class="wx-list"><div class="wx-search"><span class="wx-searchbox">${icon('search')}<i>搜索</i></span><span class="wx-plus wx-menu-wrap">${icon('plusC')}${ui.openMenu==='plus'?wxMenu('plus'):''}</span></div><div class="wx-pin">${icon('menu3')}<span>3个置顶聊天</span><span class="wx-pin-caret">${icon('caret')}</span></div><button class="wx-item on" title="${status}">${`<div class="wx-avatar wx-lu">陆</div>`}<span class="wx-item-main"><span class="wx-item-row"><b>陆遥</b><time>${last?last.time:'14:12'}</time></span><span class="wx-item-row"><small>${preview}</small>${ui.unread?'<i class="wx-unread">1</i>':''}</span></span></button>${WX_LIST.map(c=>`<span class="wx-item dead"><div class="wx-avatar wx-lu" style="background:${c.color}">${c.key}</div><span class="wx-item-main"><span class="wx-item-row"><b>${c.name}</b><time>${c.time}</time></span><span class="wx-item-row"><small>${c.preview}</small>${c.mute?'<i class="wx-mute">'+icon('lock')+'</i>':c.dot?'<i class="wx-red-dot"></i>':''}</span></span></span>`).join('')}</aside>`}
function chatView(){const wide=innerWidth>=700;const status=state.stage>=7?'文字连接 · 语音不稳定':state.stage>=6?'现场连接':'在线';const cur=puzzles[state.stage];const lastMsg=state.messages[state.messages.length-1];const ph=cur.input?cur.input.placeholder:lastMsg&&lastMsg.who==='lu'&&lastMsg.text.endsWith('？')?'回复她…':chatReplies.objective[state.stage].f;const chat=`<section class="wx-chat"><header class="wx-head"><div class="wx-peer"><b>陆遥</b><small class="${state.stage>=7?'reconnect':''}">${status}</small></div><div class="wx-head-tools"><span class="wx-tool wx-menu-wrap" data-action="wx-menu" data-id="record" title="聊天记录">${icon('chat')}</span><span class="wx-tool wx-caret wx-menu-wrap" data-action="wx-menu" data-id="record" title="更多">${icon('caret')}${ui.openMenu==='record'?wxMenu('record'):''}</span><span class="wx-tool wx-menu-wrap" data-action="wx-menu" data-id="call" title="语音通话">${icon('phone')}${ui.openMenu==='call'?wxMenu('call'):''}</span><span class="wx-tool wx-menu-wrap" data-action="wx-menu" data-id="more" title="更多">${icon('more')}${ui.openMenu==='more'?wxMenu('more'):''}</span></div></header><div class="wx-messages">${state.messages.map((m,i)=>wxRow(m,state.messages[i-1])).join('')}${ui.typing?'<div class="wx-row"><div class="wx-avatar wx-lu">陆</div><div class="wx-pop wx-typing" aria-label="对方正在输入"><i></i><i></i><i></i></div></div>':''}</div><div class="wx-typeline ${ui.typing?'':'off'}" aria-live="polite">陆遥正在输入<i></i><i></i><i></i></div><form class="wx-dock" data-form="wx-send"><div class="wx-chips"><button type="button" data-action="reply" data-id="objective" ${chatBusy()?'disabled':''}>确认当前任务</button><button type="button" data-action="reply" data-id="status" ${chatBusy()?'disabled':''}>你那边还好吗？</button>${state.stage>=7?'<button type="button" data-action="doc" data-id="outside">查看外部接应</button>':''}</div><div class="wx-inputbox"><input name="text" aria-label="输入消息" placeholder="${ph}" autocomplete="off" maxlength="120"></div><div class="wx-toolbar"><span class="wx-ticon">${icon('emoji')}</span><span class="wx-ticon">${icon('cube')}</span><span class="wx-ticon">${icon('folder')}</span><span class="wx-ticon wx-menu-wrap" data-action="wx-menu" data-id="shot" title="截图">${icon('scissors')}<span class="wx-ticon wx-caret">${icon('caret')}</span>${ui.openMenu==='shot'?wxMenu('shot',true):''}</span><span class="wx-ticon">${icon('mic')}</span><span class="wx-toolbar-pad"></span><span class="wx-ticon dim" title="语音输入">${icon('circleF')}</span><button class="wx-send" type="submit">发送</button></div></form></section>`;if(!wide)return `<div class="wx-root">${chat}</div>`;return `<div class="wx-root wide">${wxRail()}${wxList()}${chat}</div>`}
function notesView(){const live=!(ui.noteTab>=0&&ui.noteTab<state.stage);const p=puzzles[live?state.stage:ui.noteTab],hintCount=live?(state.hints[state.stage]||0):0;return `<div class="on-root"><div class="on-bar"><span class="on-app">调查便签</span><span class="on-case">HC-19-041 · 调查记录</span><span class="on-space"></span><button data-action="audio">${state.audio?'声音开启':'静音'}</button><button data-action="menu">会话</button></div><div class="on-body"><nav class="on-nav">${puzzles.map((_,i)=>{const locked=i>state.stage;const cls=i===ui.noteTab&&!live?'viewing':i===state.stage&&live?'current':i<state.stage?'done':'';return `<button class="${cls}" ${locked?'disabled':`data-action="note-tab" data-id="${i}"`} title="${esc(phases[i])}"><small>${String(i+1).padStart(2,'0')}</small><span>${esc(phases[i])}</span>${i<state.stage?'<i class="on-done">✓</i>':locked?'<i class="on-lock">'+icon('lock')+'</i>':''}</button>`}).join('')}</nav><main class="on-page">${live?`<p class="on-eyebrow">第 ${state.stage+1} 节 · 共 12 节</p><h3>${p.q}</h3><p class="case-lead">${state.stage===0?'先放大原图中的远窗，记录看得见的细节。':state.stage===11?'原图与聊天记录都可以回查。不需要赶时间。':'把查到的依据留在这里，再作判断。'}</p>${p.type==='timeline'?timelineView():p.type==='rescue'?rescueView():p.input?`<div class="open-case input-case"><p>${p.input.askText}</p><small>把答案打进微信发给她。线索在资料里。</small></div>`:`<div class="open-case">${p.options.map((o,i)=>`<button data-action="answer" data-id="${i}"><em>${'ABC'[i]}</em>${o}</button>`).join('')}</div>`}<div class="answer-feedback" role="status">${esc(ui.feedback)}</div>${hintCount?`<div class="hint">${esc(p.hint[Math.min(hintCount-1,p.hint.length-1)])}</div>`:''}<div class="case-actions"><button class="text-button" data-action="hint">${hintCount?'再给一点提示':'需要一点提示'}</button><span class="saving">${state.seen.length}份记录已读</span></div>`:readSection(ui.noteTab)}<details class="evidence-pins"${live?'':' hidden'}><summary>已查看的材料与收藏</summary>${state.seen.map(id=>{const d=docs.find(d=>d.id===id);return d?`<button data-action="doc" data-id="${id}">${state.notes.includes(id)?'◆ ':''}${esc(d.title)}</button>`:''}).join('')}</details><details class="personal-notes"${live?'':' hidden'}><summary class="case-lead" style="cursor:pointer;margin-top:12px">我的随手记</summary><textarea aria-label="个人调查记录" placeholder="记下暂时无法解释的事…">${esc(state.personal||'')}</textarea></details></main></div></div>`}
function timelineView(){return `<form data-form="timeline">${[0,1,2].map((x)=>`<label class="timeline-item"><span>${x+1}</span><select name="event${x}" aria-label="第${x+1}件事"><option value="">选择记录</option><option value="observe">观察对窗与重复物件</option><option value="test">11月8日做杯子测试</option><option value="retreat">搬离客厅，取消视频会议</option></select></label>`).join('')}<button class="primary" style="margin-top:10px;font-size:13px;width:100%">核对顺序</button></form>`}
function rescueView(){const sets=[['她握着两段橙色绳。应该追踪哪一段？',['从腰侧器材扣连续连出的新绳，核对五米双结。','颜色更鲜艳、但一端有断口的那段。','让她从眼前最近的门出去。']],['「我摸到双结了。眼前走廊至少二十米。」',['让她按二十米继续走。','外部起点到双结是五米，沿连续绳回去，先不凭目测选门。','双结就是入口，可以放开绳。']],['「蓝胶布在手里了。我摸到门楔。」',['让她回头拍一张完整照片。','关闭电脑，把这当作已经救出。','请外部人员确认门楔同时移动，再让她跨出入口。']]];const [q,opts]=sets[Math.min(state.rescue,2)];return `<p class="notice">${q}</p><div class="rescue-options open-case">${opts.map((o,i)=>`<button data-action="rescue" data-id="${i}">${o}</button>`).join('')}</div>`}
function readerView(){if(ui.reader==='room')return photoView();if(ui.reader==='welcome')return `<div class="rp-toolbar"><button data-action="open-window" data-id="files">${icon('back')}硬盘</button><div class="address">HC_ARCHIVE / 开始之前.txt</div></div><article class="doc"><h1>开始之前</h1><p>陆遥发来了一块旧硬盘。她想请你找一张，能看清窗外的照片。</p><p>打开桌面的 HC_ARCHIVE 移动硬盘，进「原始影像」，先看客厅西窗那张原图。</p><p>照片可以放大。资料里出现的名字和地点，丢进「芦苇搜索」就能查。</p><p>聊天里收到的附件会一直留在记录里。要整理判断，就用「调查便签」，也可以随手写点自己的话。</p><p>窗口能拖动缩放，也能最小化，任务栏能唤回来。Shift + Esc 是开始菜单。</p><p class="meta">进度仅保存在当前浏览器。故事、网页和人物均为虚构。包含不安影像和空间异常，无突脸惊吓。</p></article>`;const d=docs.find(d=>d.id===ui.reader);if(!d)return '<div class="empty">未找到文件</div>';if(d.kind==='video')return videoView(d);return `<div class="rp-toolbar"><button data-action="open-window" data-id="files">${icon('back')}硬盘</button><div class="address">${esc(d.url||'HC_ARCHIVE / '+d.folder)}</div><button data-action="pin" data-id="${d.id}">${icon('pin')}${state.notes.includes(d.id)?'已收藏':'留在便签'}</button></div><article class="doc">${d.body}</article>`}
function photoView(){return `<div class="ph-root"><div class="ph-toolbar"><span class="ph-name">041-W03_客厅西窗.jpg</span><span class="ph-tools"><button data-action="zoom-out" title="缩小">${icon('zoomout')}</button><span class="ph-zoom">${Math.round(ui.zoom*100)}%</span><button data-action="zoom-in" title="放大">${icon('zoomin')}</button><button data-action="reset-zoom" title="复位">${icon('refresh')}</button><button data-action="compare" title="并排核对原始材料">${icon('photo')}</button></span></div><div class="photo-stage ${ui.zoom>1?'zoomed':''}"><div class="photo-sheet" style="transform:scale(${ui.zoom})"><img src="assets/room.png" alt="西窗原图，窗外有一扇布置相似的窗"><div class="maintenance-label">安顺宽带<br>松亭片区 / ST-2E</div><button class="photo-hotspot hot-window" data-action="inspect" data-id="window" aria-label="放大远窗">+<span class="hot-label">远窗</span></button><button class="photo-hotspot hot-labelspot" data-action="inspect" data-id="label" aria-label="查看维修贴纸">+<span class="hot-label">维修标签</span></button></div></div>${ui.observation?`<div class="observation">${esc(ui.observation)}</div>`:''}<div class="ph-caption"><span class="ph-cap-info">2019.11.18　客厅西窗 / 沈屹项目原始记录 · 原始文件只读</span><span class="ph-cap-actions"><button data-action="doc" data-id="manifest">影像清单</button><button data-action="doc" data-id="plan">户型记录</button><button data-action="doc" data-id="exterior">外墙记录</button><button data-action="open-window" data-id="notes">记录观察</button></span></div></div>`}
const cupFrames=[['00:00','机位固定在客厅内。对面的窗台是空的。'],['00:17','陈苇把白色杯子放在近处窗台。远窗没有同步动作。'],['00:43','一只手从远处桌子下方伸出。那里没有人能够站立的位置。'],['00:51','杯子被放上远窗。手腕没有转动，杯口却慢慢转正。录像在这里停止。']];
const ceilingFrames=[['00:00','陈苇将摄影杆伸出窗外。镜头正在转向本应出现的外墙。'],['00:09','画面里出现室内天花板，镜头的位置却仍在窗外。'],['00:15','现在能看见她的后脑。她仍举着杆子，朝窗外看。'],['00:24','几个人先后望向同一处没有镜头的墙面。录像终止。']];
function videoView(d){const isCup=d.id==='cup',frames=isCup?cupFrames:ceilingFrames,f=Math.min(ui.videoFrame,3);return `<div class="video-body"><div class="toolbar photo-tools"><span class="mono">${isCup?'CW_TEST_1108':'HC_041_FIELD'} · 原始录像</span><span style="margin-left:auto;font-size:13px">分段回放 / 文字稿同步</span></div><div class="video-frame"><img src="assets/${isCup?'room':'ceiling'}.png" alt="${isCup?'客厅杯子测试画面':'窗外机位拍到室内的录像画面'}" style="transform:scale(${isCup?(f>=2?1.25:1):1+f*.025}) ${isCup&&f>=2?'translate(-5%,4%)':''}">${isCup&&f>=1?`<div class="video-object" style="${f===1?'left:53%;top:61%;width:17px;height:22px;':f>=2?'left:71%;top:35%;':''}"></div>`:''}${isCup&&f>=2?'<div class="video-hand"></div>':''}<span class="video-tc">REC ${frames[f][0]}</span><div class="video-stage-label">${frames[f][1]}</div></div><div class="timeline-track"><div style="width:${(f+1)*25}%"></div></div><div class="video-controls">${frames.map(([t],i)=>`<button class="${f===i?'current':''}" data-action="video-frame" data-id="${i}">${t}</button>`).join('')}<button class="next" data-action="video-frame" data-id="${Math.min(f+1,3)}">${f===3?'回放末段':'下一段 →'}</button><button data-action="open-window" data-id="notes">记入便签</button></div></div>`}
function spaceView(){const matched=known(state,'matched'),reg=known(state,'registered');return `<div class="mt-root"><div class="mt-menubar"><b>空间复核 · HC-19-041</b><span>文件</span><span>编辑</span><span>查看</span><span>工作流</span><span>工具</span><span>帮助</span><em class="mt-pill ${ui.active?'on':''}">${ui.active?'关联活动中':'关联已暂停'}</em></div><div class="mt-main"><aside class="mt-pane mt-left"><h5>项目</h5><p class="mt-tree mt-root-item">HC-19-041</p><p class="mt-tree">照片 (7)</p><p class="mt-tree ${reg?'on':''}">复核视点 (${reg?1:0})</p><p class="mt-tree">标记 (0)</p><h5>参考</h5><button class="mt-link" data-action="doc" data-id="manual">使用说明 ↗</button><button class="mt-link" data-action="doc" data-id="archives">旧建筑对照 ↗</button><div class="mt-note">查看原图仅读取资料。<br>激活关联会更新当前空间。</div></aside><div class="mt-viewport ${ui.active?'active':''}"><div class="mt-grid"></div><img src="assets/${reg?(ui.active?'corridor':'corridor-paused'):'room'}.png" alt="空间关联预览"><div class="anchor-map"><svg viewBox="0 0 480 90"><path d="M35 65V20h160v50h100V15h140v55H295 M110 20v45 M195 45h100"/><circle cx="110" cy="45" r="4"/><circle cx="295" cy="45" r="4"/><path d="M110 45L295 45" stroke-dasharray="4 5"/></svg><div class="match-line"></div></div><span class="mt-status">${matched?'MATCH / 3处局部特征一致':'REFERENCE / YN-94-06 + YX-08-12'}<br>${reg?'SITE / 陆遥的现场终端已接入':'SITE / 等待局部复核'}</span><span class="mt-open">开放方向 · 未注册</span></div><aside class="mt-pane mt-right"><h5>参考特征</h5><p class="mt-hintline">${matched?'局部特征已核实。连接方向仍然存在偏差。':'从旧照片记录中选出可核对的结构特征。'}</p><div class="anchor-options">${['窗台不对称缺口','三个固定孔','回折线槽','同款家具','拍摄年份'].map((name,i)=>`<button class="${ui.anchors.includes(i)?'selected':''}" data-action="anchor" data-id="${i}"><i></i>${name}</button>`).join('')}</div><div class="mt-actions"><button data-action="match">核实局部特征</button><button data-action="register" ${!matched||state.stage<6?'disabled':''}>注册走廊局部</button><button data-action="toggle-link" ${!reg?'disabled':''}>${ui.active?'暂停关联':'测试恢复同一关联'}</button><button class="warning" data-action="complete-map" ${!reg?'disabled':''}>补齐覆盖并定位</button></div></aside></div><div class="spatial-log">${ui.spaceLog.length?ui.spaceLog.map(esc).join('<br>'):'READY　保留当前缺失方向。'}</div><div class="mt-statusbar"><span>${ui.active?'LINK ACTIVE':'LINK IDLE'}</span><span>YX-08-12 → HC-19-041</span><span class="mt-dim">覆盖未闭合 · 保留缺失方向</span></div></div>`}
function openDoc(id){if(id==='space'){openWindow('space');return}if(id==='room'){flag(state,'room-viewed')}else{visit(state,id)}ui.reader=id;ui.videoFrame=0;ui.zoom=1;ui.observation='';wins.reader.title=id==='room'?'影像查看器 · 客厅西窗':docs.find(d=>d.id===id)?.title||'文件';focus('reader');save();render()}
function handleAnswer(answer){const r=resolve(state,answer);if(!r.ok){ui.feedback=r.reason==='evidence'?'还有材料没看全，或者观察没做完。已打开的文件可以回查。':r.message||'先继续调查。';render();return}ui.feedback='';r.messages.forEach((m,i)=>queueLu(m,undefined,1300+i*1700+Math.random()*500));afterAdvance(r.previous);save();focus('notes');render();toast('记下了。新问题在便签里')}
function afterAdvance(previous){const a={0:'manifest',1:'plan',2:'notes',3:'cup',4:'company',5:'entrance',6:'outside',7:'green',8:'log',9:'experiment',10:'rope'};if(a[previous])queueLu(['这份记录我放在这里。','资料发你了，聊天里能看。','有份新材料，你核对一下。'][ui.attachIdx++%3],a[previous],2200);if(previous===6){ui.active=false;ui.spaceLog.push('PAUSED　现场异常后已停止新增关联。');flag(state,'arrival')}}
function renderEnding(){const e=endings[state.ending];$('#app').innerHTML=`<main class="ending ${state.ending}"><div class="ending-inner"><p class="eyebrow">HC-19-041 / SESSION ${state.ending==='safe'?'PAUSED':state.ending==='bad'?'LOCATED':'ON HOLD'}</p><h1>${e.title}</h1><p class="ending-sub">${e.sub}</p><div class="ending-lines">${e.lines.map(x=>`<p>${esc(x)}</p>`).join('')}</div><p class="ending-note">${e.note}</p><button class="primary" data-action="checkpoint">${state.ending==='safe'?'回到最后一次调查':'回到选择前'}</button><button class="secondary" data-action="restart">重新开始</button><p class="micro muted" style="font-size:13px;margin-top:25px">没有窗外 · 初版结束</p></div></main>`}
function dialog(html){const d=$('#dialog');d.innerHTML=html;d.showModal()}
function closeDialog(){const d=$('#dialog');if(d.open)d.close()}
function menu(){dialog(`<h3>当前会话</h3><p>进度保存在此浏览器，可以随时离开后继续。阅读原图不会影响现场。</p><p>当前调查　${phases[state.stage]}<br>已查看　${state.seen.length}份材料</p><div class="dialog-actions"><button class="secondary" data-action="restart">重新开始</button>${state.stage>=7?'<button class="secondary" data-action="stop">中止调查</button>':''}<button class="primary" data-action="dialog-close">继续</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
  if(ui.openMenu&&a!=='wx-menu'){ui.openMenu=''}
  if(a==='start'){start();return}if(a==='dialog-close'){closeDialog();return}if(a==='restart'){dialog('<h3>重新开始调查？</h3><p>当前浏览器里的游戏进度将被替换。其他文件不会受到影响。</p><div class="dialog-actions"><button class="secondary" data-action="dialog-close">取消</button><button class="primary" data-action="reset-confirm">重新开始</button></div>');return}if(a==='reset-confirm'){closeDialog();Object.assign(ui,{reader:'room',anchors:[],active:false,feedback:'',unread:0,spaceLog:[],typing:false,noteTab:-1,chatTally:{},attachIdx:0});start(true);return}if(a==='menu'){menu();return}if(a==='audio'){state.audio=!state.audio;save();tone();render();return}if(a==='open-window'){openWindow(id);return}if(a==='task'){if(!wins[id].min&&wins[id].z===highest){wins[id].min=true;render()}else openWindow(id);return}if(a==='close'||a==='min'){wins[id].min=true;render();return}if(a==='maximize'){const w=wins[id];if(w.restore){Object.assign(w,w.restore);w.restore=null}else{w.restore={x:w.x,y:w.y,w:w.w,h:w.h};Object.assign(w,{x:8,y:38,w:innerWidth-16,h:innerHeight-96})}focus(id);render();return}if(a==='folder'){ui.folder=id;ui.localSearch='';render();return}if(a==='doc'){openDoc(id);return}if(a==='wx-menu'){ui.openMenu=ui.openMenu===id?'':id;render();return}if(a==='wx-menu-item'){ui.openMenu='';render();return}if(a==='note-tab'){ui.noteTab=ui.noteTab===Number(id)?-1:Number(id);render();return}if(a==='zoom-in'){ui.zoom=Math.min(3.2,Math.round((ui.zoom+.2)*10)/10);render();return}if(a==='zoom-out'){ui.zoom=Math.max(1,Math.round((ui.zoom-.2)*10)/10);render();return}if(a==='edg-reload'){render();return}if(a==='search-home'){ui.lastSearch='';render();return}if(a==='query'){doSearch(id);return}if(a==='answer'){handleAnswer(Number(id));return}if(a==='hint'){state.hints[state.stage]=(state.hints[state.stage]||0)+1;save();ui.feedback='';render();return}if(a==='pin'){if(!state.notes.includes(id))state.notes.push(id);else state.notes=state.notes.filter(x=>x!==id);save();render();return}if(a==='reset-zoom'){ui.zoom=1;ui.observation='';render();return}if(a==='inspect'){flag(state,'inspect-'+id);if(id==='window'){ui.zoom=1.8;ui.observation='远窗里也有台灯、蓝色毛巾和红袋子。位置略有不同。仅凭这张照片，还不能确定原因。'}else{ui.zoom=1;ui.observation='维修贴纸：安顺宽带 / 松亭片区 / ST-2E。文字已记入观察。'}save();render();return}if(a==='compare'){dialog(`<h3>并排核对原始材料</h3><p>保留西窗原图，选择一份材料在另一侧对照。</p><div class="dialog-actions"><button class="secondary" data-action="compare-open" data-id="plan">原始户型</button><button class="primary" data-action="compare-open" data-id="exterior">西立面原片</button></div>`);return}if(a==='compare-open'){closeDialog();visit(state,id);ui.reader=id;focus('reader');save();render();const doc=$('.doc');if(doc)doc.insertAdjacentHTML('afterbegin','<figure><img src="assets/room.png" alt="用于对照的室内西窗原片"><figcaption>对照图 / 客厅西窗原始照片</figcaption></figure>');return}if(a==='video-frame'){ui.videoFrame=Number(id);if(ui.videoFrame===3){flag(state,ui.reader==='cup'?'cup-played':'ceiling-played');save()}render();return}if(a==='anchor'){const n=Number(id);ui.anchors=ui.anchors.includes(n)?ui.anchors.filter(x=>x!==n):[...ui.anchors,n];render();return}if(a==='match'){if(!['archives','manual'].every(x=>known(state,x))){toast('先核对旧建筑原始记录与工具说明。');return}if(JSON.stringify([...ui.anchors].sort())!==JSON.stringify([0,1,2])){toast('家具和拍摄年份不能替代结构对应。重新核对原始记录。');return}flag(state,'matched');ui.spaceLog.push('MATCH　3处局部结构对应 / 连接方向仍不一致。');save();render();return}if(a==='register'){flag(state,'registered');ui.active=true;ui.spaceLog.push('LINK　YX-08-12 → HC-19-041 / 局部已激活。');save();render();toast('走廊局部已注册，未补齐开放方向。');return}if(a==='toggle-link'){ui.active=!ui.active;if(!ui.active){flag(state,'trial-paused');queueLu('停住了。拖椅子的声音没有再靠近。旧告示现在看不见。',undefined,500)}else{flag(state,'trial-active');queueLu('那张2008年的告示又回来了。我没动过，门上的东西变了。',undefined,500);ui.spaceLog.push('REPEAT　同一关联恢复 / 现场告示复现。')}save();render();return}if(a==='complete-map'){dialog(`<h3>补齐覆盖并定位</h3><p>这会闭合当前项目，并定位参与会话的全部活动终端，包括本地操作室。</p><p>原项目明确标注不允许自动补齐。你仍可以取消，回查资料。</p><div class="dialog-actions"><button class="secondary" data-action="dialog-close">保持缺口</button><button class="danger" data-action="complete-confirm">确认完整重建</button></div>`);return}if(a==='complete-confirm'){closeDialog();state.checkpoint=structuredClone({...state,checkpoint:undefined});state.ending='bad';save();render();return}if(a==='rescue'){const r=rescue(state,Number(id));if(!r.ok){ui.feedback=r.message;render();return}ui.feedback='';if(state.rescue===1)queueLu('我握住腰上这一根了。五米处双结，向外拉还是连续的。',undefined,900);if(state.rescue===2)queueLu('蓝胶布在手里了。我摸到门楔，先等外面确认。',undefined,900);if(r.done)queueLu('他们看到门楔动了。我出来了。你先别挂。',undefined,1200);save();render();return}if(a==='checkpoint'){if(state.ending==='bad'&&state.checkpoint){state=hydrate(state.checkpoint)}else{state.ending=null;state.rescue=0}ui.feedback='';save();focus('notes');render();return}if(a==='stop'){closeDialog();state.ending='stop';save();render();return}if(a==='reply'){if(chatBusy())return;const r=luReply(id==='status'?'status':'objective');addMessage(r.self,'self');queueLu(r.reply,undefined,900+Math.random()*700);save();render();return}
});
document.addEventListener('click',e=>{if(ui.openMenu&&!e.target.closest('.wx-menu-wrap')){ui.openMenu='';if(typeof pane==='undefined'||pane==='chat')render()}});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const data=new FormData(f);if(f.dataset.form==='browser-search'){const raw=String(data.get('query')||'');const q=/[?&]q=/.test(raw)?decodeURIComponent(raw.split(/[?&]q=/)[1].split('&')[0].replace(/\+/g,' ')):raw;doSearch(q)}if(f.dataset.form==='file-search'){ui.localSearch=String(data.get('query')||'');render()}if(f.dataset.form==='timeline')handleAnswer([data.get('event0'),data.get('event1'),data.get('event2')]);if(f.dataset.form==='wx-send'){const text=String(data.get('text')||'').trim();if(!text)return;const cur=puzzles[state.stage];
if(chatBusy()){addMessage(text,'self');save();render();return}
if(cur.input){const r=resolveInput(state,text);if(r.ok){ui.feedback='';r.messages.forEach((m,i)=>queueLu(m,undefined,1300+i*1700+Math.random()*500));afterAdvance(r.previous);save();focus('notes');render();toast('记下了。新问题在便签里');return}if(r.reason==='evidence'){addMessage(text,'self');queueLu('先别急。你看的资料还不够下这个判断。',undefined,900);save();render();return}if(r.reason==='wrong'&&/[0-9一二三四五六七八九十两号栋]/.test(text)){addMessage(text,'self');queueLu(r.message,undefined,900+Math.random()*500);save();render();return}}
addMessage(text,'self');
const isWhy=/为什么|为啥|啥意思|什么意思|怎么回事|凭什么|为何|啥呀/.test(text);
const isTask=/做什么|干嘛|干什么|接下来|怎么查|怎么核|怎么办|咋办|任务|先看|查什么|看什么|怎么弄|哪一步/.test(text);
const isStatus=/你好吗|还好吗|还好|没事吧|安全|怎么样|状态/.test(text);
if(isWhy)queueLu(chatReplies.objective[state.stage].why,undefined,900+Math.random()*600);
else if(isTask)queueLu(luReply('objective').reply,undefined,900+Math.random()*700);
else if(isStatus)queueLu(luReply('status').reply,undefined,900+Math.random()*600);
else queueLu(['收到。','嗯，我在。','好。','嗯。','你继续，我看着。'][ui.ackIdx++%5],undefined,700+Math.random()*500);
save();render()}});
function doSearch(q){ui.lastSearch=String(q||'').trim();state.history.push({query:ui.lastSearch});save();focus('browser');render()}
document.addEventListener('input',e=>{if(e.target.matches('.wx-inputbox input')){const btn=$('.wx-send');if(btn)btn.classList.toggle('has-text',Boolean(e.target.value.trim()))}if(e.target.id==='photo-zoom'){ui.zoom=Number(e.target.value);const sheet=$('.photo-sheet');if(sheet)sheet.style.transform=`scale(${ui.zoom})`;}if(e.target.matches('.personal-notes textarea')){state.personal=e.target.value;save()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#dialog').open)closeDialog();if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();openWindow('browser');setTimeout(()=>$('input[aria-label="搜索网页与档案"]')?.focus(),0)}});
function bindWindowGestures(){document.querySelectorAll('.window').forEach(el=>{el.addEventListener('pointerdown',()=>{const id=el.dataset.window;wins[id].z=++highest;el.style.zIndex=highest;document.querySelectorAll('.window.focused').forEach(x=>x.classList.remove('focused'));el.classList.add('focused')})});document.querySelectorAll('[data-drag],[data-resize]').forEach(el=>{el.addEventListener('pointerdown',e=>{if(innerWidth<=700||e.target.closest('button'))return;const id=el.dataset.drag||el.dataset.resize,w=wins[id],target=el.closest('.window'),sx=e.clientX,sy=e.clientY,start={x:w.x,y:w.y,w:w.w,h:w.h};el.setPointerCapture(e.pointerId);const move=ev=>{if(el.dataset.resize){w.w=Math.max(300,Math.min(innerWidth-w.x-4,start.w+ev.clientX-sx));w.h=Math.max(220,Math.min(innerHeight-w.y-53,start.h+ev.clientY-sy));target.style.width=w.w+'px';target.style.height=w.h+'px'}else{w.x=Math.max(0,Math.min(innerWidth-100,start.x+ev.clientX-sx));w.y=Math.max(30,Math.min(innerHeight-100,start.y+ev.clientY-sy));target.style.left=w.x+'px';target.style.top=w.y+'px'}};const up=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up)};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up);e.preventDefault()})});const stage=$('.photo-stage');if(stage){stage.addEventListener('pointermove',e=>{if(ui.zoom<=1)return;const r=stage.getBoundingClientRect();const sheet=$('.photo-sheet');if(sheet)sheet.style.transformOrigin=`${Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100))}% ${Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100))}%`})}}
window.addEventListener('resize',()=>{fitWindows();if(state.started&&!state.ending)render()});
window.addEventListener('pagehide',()=>{flushPending();save()});
window.__game={get state(){return state},get ui(){return ui},openDoc,openWindow,render,save};
render();

